# This code has been fully generated by an AI.
"""LAN-Server: eine WebSocket-Nachricht trägt Bild und Zustand gemeinsam, REST für Aktionen und Anmeldung.

Die Seiten liefert der Client selbst aus; hier gibt es nur Daten, und jede Aktion prüft die Rolle.
"""

import asyncio
import logging
import uuid
from pathlib import Path
from urllib.parse import unquote

from starlette.applications import Starlette
from starlette.middleware import Middleware
from starlette.middleware.cors import CORSMiddleware
from starlette.requests import Request
from starlette.responses import FileResponse, JSONResponse, Response
from starlette.routing import Route, WebSocketRoute
from starlette.websockets import WebSocket, WebSocketDisconnect

from .app import App, UserError
from .library import MemeLibrary
from .lobby import ROLE_LABEL, Lobby, LobbyError

log = logging.getLogger(__name__)
MAX_MEDIA = 100 * 1024 * 1024
ROOT = Path(__file__).resolve().parent.parent
MEDIA_DIR = ROOT / "data" / "media"
MEMES_DIR = ROOT / "memes"


class MediaStore:
    """Steckbriefbilder auf der Platte; sie überleben keinen Neustart, sonst wären sie ewiger Ballast."""

    def __init__(self, folder: Path):
        self.folder = folder
        self.folder.mkdir(parents=True, exist_ok=True)
        self.mimes: dict[str, str] = {}
        for path in folder.iterdir():
            path.unlink(missing_ok=True)

    def add(self, body: bytes, mime: str) -> str:
        key = uuid.uuid4().hex
        (self.folder / key).write_bytes(body)
        self.mimes[key] = mime
        return key


def create_server(app: App, media_dir: Path = MEDIA_DIR, lobby: Lobby | None = None,
                  memes_dir: Path = MEMES_DIR) -> Starlette:
    def changed(message: str | None) -> None:
        app.board_rev += 1
        if message:
            app.message = message

    # Zuerst die Bibliothek: sie übernimmt einmalig das alte Soundboard aus media_dir.
    library = MemeLibrary(memes_dir, media_dir.parent / "soundboard.json", changed, legacy=media_dir)
    # Dasselbe Objekt, damit der Zustand den Fortschritt ohne Umweg sieht.
    app.keying = library.keying
    store = MediaStore(media_dir)
    lobby = lobby or app.lobby or Lobby(None, "admin")
    def who(request: Request) -> tuple[str, dict | None]:
        auth = request.headers.get("authorization", "")
        token = auth[7:].strip() if auth.lower().startswith("bearer ") else ""
        return token, lobby.session(token)

    def denied(session: dict | None) -> JSONResponse:
        if session is None:
            return JSONResponse({"ok": False, "message": "Nicht angemeldet. Client neu starten."},
                                status_code=401)
        return JSONResponse({"ok": False, "message": "Nur die Moderation darf das."}, status_code=403)

    def moderator(request: Request) -> JSONResponse | None:
        session = who(request)[1]
        return None if session and session["role"] == "moderator" else denied(session)

    async def hello(request: Request):
        return JSONResponse({"app": "hebocon", "id": lobby.server_id, "port": request.url.port})

    async def join(request: Request):
        data = await request.json() if await request.body() else {}
        try:
            result = await asyncio.to_thread(lobby.join, data.get("name", ""), data.get("password", ""),
                                             data.get("token", ""))
        except LobbyError as exc:
            log.warning("Anmeldung „%s“ abgelehnt: %s", data.get("name", ""), exc)
            return JSONResponse({"ok": False, "code": exc.code, "message": str(exc)}, status_code=400)
        client = request.client.host if request.client else "?"
        if result["role"] == "player":
            app.player_joined(result["slot"], result["name"])
            log.info("Spieler %d „%s“ angemeldet (%s).", result["slot"], result["name"], client)
        else:
            log.info("%s angemeldet (%s).", ROLE_LABEL[result["role"]], client)
        return JSONResponse({"ok": True, **result})

    async def leave(request: Request):
        token, session = who(request)
        if session is None:
            return denied(session)
        slot = await asyncio.to_thread(lobby.leave, token)
        if slot:
            log.info("Spieler %d „%s“ hat den Platz freigegeben.", slot, session["name"])
        return JSONResponse({"ok": True})

    async def action(request: Request):
        name = request.path_params["name"]
        data = await request.json() if await request.body() else {}
        session = who(request)[1]
        role = session["role"] if session else None
        # Bühnen und Spieler melden nur das Ende ihrer Medien; Spieler zünden außerdem ihre eigene Ulti.
        if role == "player" and name == "ulti":
            if not session["slot"]:
                return JSONResponse({"ok": False, "message": "Du hast gerade keinen Spielerplatz."},
                                    status_code=403)
            data = {"player": session["slot"]}
        elif not (role == "moderator" or (role and name == "cue" and data.get("kind") == "ended")):
            return denied(session)
        if not (name == "cue" and data.get("kind") == "ended"):
            log.info("Aktion %s von %s", name, lobby.describe(who(request)[0]))
        try:
            await asyncio.to_thread(app.act, name, data)
        except UserError as exc:
            app.message = str(exc)
            log.warning("Aktion %s abgelehnt: %s", name, exc)
            return JSONResponse({"ok": False, "message": str(exc)}, status_code=400)
        except TypeError as exc:
            return JSONResponse({"ok": False, "message": f"Ungültige Daten: {exc}"}, status_code=400)
        return JSONResponse({"ok": True})

    async def upload(request: Request):
        if (refused := moderator(request)) is not None:
            return refused
        body = await request.body()
        if not body or len(body) > MAX_MEDIA:
            message = "Datei leer oder größer als 100 MB."
            return JSONResponse({"ok": False, "message": message}, status_code=400)
        mime = request.headers.get("content-type", "application/octet-stream")
        name = unquote(request.headers.get("x-name", ""))
        if request.headers.get("x-board") != "1":
            key = await asyncio.to_thread(store.add, body, mime)
            return JSONResponse({"ok": True, "url": f"/media/{key}", "name": name, "mime": mime})
        entry = await asyncio.to_thread(library.add, body, mime, name, request.headers.get("x-key") == "1")
        return JSONResponse({"ok": True, **library.public(entry)})

    async def board(_: Request):
        return JSONResponse(library.board())

    async def download(request: Request):
        key = request.path_params["key"]
        mime = store.mimes.get(key)
        if mime is None:
            return Response(status_code=404)
        return FileResponse(store.folder / key, media_type=mime)

    async def meme(request: Request):
        found = library.path(request.path_params["file"])
        if found is None or not found[0].is_file():
            return Response(status_code=404)
        return FileResponse(found[0], media_type=found[1])

    async def change(request: Request):
        if (refused := moderator(request)) is not None:
            return refused
        file = request.path_params["file"]
        if request.method == "DELETE":
            if not await asyncio.to_thread(library.remove, file):
                message = "Meme nicht gefunden oder wird gerade freigestellt."
                return JSONResponse({"ok": False, "message": message}, status_code=400)
            return JSONResponse({"ok": True})
        name = str((await request.json()).get("name") or "").strip()
        if not name or not library.rename(file, name):
            message = "Kachel nicht gefunden oder Name leer."
            return JSONResponse({"ok": False, "message": message}, status_code=400)
        return JSONResponse({"ok": True})

    async def stream(ws: WebSocket):
        await ws.accept()
        token = ws.query_params.get("token", "")
        if lobby.session(token) is None:
            # Eigener Code, damit der Client „neu anmelden“ von einem Netzaussetzer unterscheiden kann.
            await ws.close(code=4401)
            return
        # Fenster ohne Kamerabild (frames=0) sparen im WLAN viel Bandbreite.
        frames = ws.query_params.get("frames", "1") != "0"
        client = ws.client.host if ws.client else "?"
        lobby.connected(token, +1)
        log.info("Verbunden: %s (%s) · %s", lobby.describe(token), client, _online(lobby))
        last_seq, idle = -1, 0
        try:
            while True:
                seq, packet = app.packet
                if seq != last_seq and packet:
                    last_seq, idle = seq, 0
                    if not frames:
                        packet = packet[:4 + int.from_bytes(packet[:4], "little")]
                    await ws.send_bytes(packet)
                else:
                    idle += 1
                    # Ohne Kamera kommen keine Frames; Zustand trotzdem regelmäßig schicken.
                    if idle % 25 == 0:
                        app.publish_idle()
                await asyncio.sleep(0.01)
        except (WebSocketDisconnect, RuntimeError, OSError):
            pass
        finally:
            lobby.connected(token, -1)
            log.info("Getrennt: %s (%s) · %s", lobby.describe(token), client, _online(lobby))

    return Starlette(routes=[
        Route("/lobby/hello", hello, methods=["GET"]),
        Route("/lobby/join", join, methods=["POST"]),
        Route("/lobby/leave", leave, methods=["POST"]),
        Route("/api/{name}", action, methods=["POST"]),
        Route("/media", upload, methods=["POST"]),
        Route("/media", board, methods=["GET"]),
        Route("/media/{key}", download, methods=["GET"]),
        Route("/memes/{file}", meme, methods=["GET"]),
        Route("/memes/{file}", change, methods=["PATCH", "DELETE"]),
        WebSocketRoute("/ws", stream),
    ], middleware=[
        # Die Seiten kommen vom lokalen Webserver des Clients, also von einer anderen Herkunft.
        Middleware(CORSMiddleware, allow_origins=["*"], allow_methods=["*"], allow_headers=["*"]),
    ])


def _online(lobby: Lobby) -> str:
    counts = lobby.public()["online"]
    return f"online: {counts['moderator']} Moderation, {counts['stage']} Bühne, {counts['player']} Spieler"
